import React, { useState } from "react";
import ChatWindow from "./components/ChatWindow";
import ChatInput from "./components/ChatInput";
import { sendMessage, uploadPDF } from "./services/api";
import "./App.css";

function App() {
  const [messages, setMessages] = useState([]);

  // ---------------- CHAT ----------------
  const handleSend = async (text) => {
    if (!text.trim()) return;

    // ✅ user message
    setMessages((prev) => [
      ...prev,
      { sender: "user", text }
    ]);

    // ✅ typing
    setMessages((prev) => [
      ...prev,
      { sender: "bot", text: "Typing..." }
    ]);

    try {
      const res = await sendMessage(text);
      const botReply = res?.data?.answer || "No reply from server";

      setTimeout(() => {
        setMessages((prev) => {
          const updated = [...prev];
          updated.pop(); // remove typing
          return [...updated, { sender: "bot", text: botReply }];
        });
      }, 800);

    } catch (err) {
      console.error(err);

      setTimeout(() => {
        setMessages((prev) => {
          const updated = [...prev];
          updated.pop();
          return [...updated, { sender: "bot", text: "⚠ Server error" }];
        });
      }, 800);
    }
  };

  // ---------------- PDF UPLOAD ----------------
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setMessages((prev) => [
      ...prev,
      { sender: "user", text: `📄 Uploaded: ${file.name}` }
    ]);

    try {
      await uploadPDF(file);

      setMessages((prev) => [
        ...prev,
        { sender: "bot", text: "✅ PDF uploaded successfully! Now ask questions from it." }
      ]);

    } catch (err) {
      console.error(err);

      setMessages((prev) => [
        ...prev,
        { sender: "bot", text: "❌ PDF upload failed" }
      ]);
    }
  };

  return (
    <div className="container">
      <h2>EduSaarthi</h2>
      <p>Multilingual University Helpdesk</p>

      {/* 📄 PDF Upload */}
      <input
        type="file"
        accept="application/pdf"
        onChange={handleFileUpload}
        style={{ marginBottom: "10px" }}
      />

      <ChatWindow messages={messages} />
      <ChatInput onSend={handleSend} />
    </div>
  );
}

export default App;
